import express from "express";
import { fileURLToPath } from "node:url";
import {
  connectDB,
  getAllBooks,
  findBooksByGenre,
  findBooksByMaxPrice,
  getThreeCheapestBooks,
  addBook,
} from "./database.js";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database.js.`,
    });
  }
  res.json(data);
}

app.get("/api/books", async (req, res) => {
  try {
    sendList(res, await getAllBooks(), "getAllBooks");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/books/search", async (req, res) => {
  try {
    sendList(res, await findBooksByGenre(req.query.genre), "findBooksByGenre");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/books/filter", async (req, res) => {
  const maxPrice = Number(req.query.maxPrice);
  if (Number.isNaN(maxPrice)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findBooksByMaxPrice(maxPrice), "findBooksByMaxPrice");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/books/top", async (req, res) => {
  try {
    sendList(res, await getThreeCheapestBooks(), "getThreeCheapestBooks");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/books", async (req, res) => {
  try {
    const saved = await addBook(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addBook() did not return the saved book. Complete it in database.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
